import ratpack.server.ServerConfig;
import ratpack.server.ServerConfigBuilder;

import java.util.function.Consumer;

/**
 * An imposition object for imposing server configuration.
 * <p>
 * This type works with the {@link Impositions} mechanism.
 * It allows arbitrary {@link ServerConfig} to be imposed.
 * <p>
 * Every {@link ServerConfigBuilder} is imposition aware.
 * The impositions are captured when the builder is created.
 * <p>
 * If a {@code ServerConfigImpositions} is present, its function will be applied to the builder during {@link ServerConfigBuilder#build()}.
 * Note that the {@link ForceDevelopmentImposition} and {@link ForcePortImposition} are applied <b>after</b> this imposition.
 *
 * @see Impositions
 * @since 1.2
 */
public final class ServerConfigImpositions implements Imposition {

  private final Consumer<? super ServerConfigBuilder> action;

  private ServerConfigImpositions(Consumer<? super ServerConfigBuilder> action) {
    this.action = action;
  }

  /**
   * Creates an imposition that applies the given function to the server config builder.
   *
   * @param impositions the impositions
   * @return an impositions object, for the impositions registry
   */
  public static ServerConfigImpositions of(Consumer<? super ServerConfigBuilder> impositions) {
    return new ServerConfigImpositions(impositions);
  }

  /**
   * Applies the impositions to the given builder.
   *
   * @param builder a server config builder
   */
  public void apply(ServerConfigBuilder builder) {
    action.accept(builder);
  }
